// fileReplacementsProvider handles {file.*} replacements,
// reading a file from disk and replacing with its contents.
type fileReplacementProvider struct {
	prefix  string
	maxSize int
}

func (f fileReplacementProvider) replace(key string) (any, bool) {
	prefix := f.prefix
	if prefix == "" {
		prefix = filePrefix
	}
	if !strings.HasPrefix(key, prefix) {
		return nil, false
	}

	filename := key[len(prefix):]
	maxSize := f.maxSize
	if maxSize <= 0 {
		maxSize = 1024 * 1024
	}

	ctx := ActiveContext()
	cfg := ctx.cfg
	moduleGroups := len(ctx.moduleInstances)
	moduleLineage := len(ctx.ancestry)

	var (
		hasSink           bool
		writerKeyCount    int
		unfilteredDefault bool
		usingFSMap        bool
		includeRules      []string
		excludeRules      []string
	)

	if _, ok := ctx.Filesystems().(*filesystems.FilesystemMap); ok {
		usingFSMap = true
	}

	if cfg != nil {
		if cfg.filesystems != nil {
			if _, ok := cfg.filesystems.(*filesystems.FilesystemMap); ok {
				usingFSMap = true
			}
		}
		if logging := cfg.Logging; logging != nil {
			hasSink = logging.Sink != nil
			writerKeyCount = len(logging.writerKeys)
			if logging.Logs != nil {
				if cl := logging.Logs[DefaultLoggerName]; cl != nil {
					includeRules = cl.Include
					excludeRules = cl.Exclude
					unfilteredDefault = len(includeRules) == 0 && len(excludeRules) == 0
				}
			}
		}
	}

	body, err := readFileIntoBuffer(filename, maxSize)
	if err != nil {
		wd, _ := os.Getwd()
		Log().Error("placeholder: failed to read file",
			zap.String("file", filename),
			zap.String("working_dir", wd),
			zap.Int("module_groups", moduleGroups),
			zap.Int("module_lineage", moduleLineage),
			zap.Bool("has_sink", hasSink),
			zap.Int("writer_keys", writerKeyCount),
			zap.Bool("unfiltered_default_log", unfilteredDefault),
			zap.Bool("filesystem_map", usingFSMap),
			zap.Strings("log_include", includeRules),
			zap.Strings("log_exclude", excludeRules),
			zap.Error(err))
		return nil, true
	}
	return string(body), true
}

// globalDefaultReplacementsProvider handles replacements
// that can be used in any context, such as system variables,
// time, or environment variables.
type globalDefaultReplacementProvider struct{}

func (f globalDefaultReplacementProvider) replace(key string) (any, bool) {
	// check environment variable
	const envPrefix = "env."
	if strings.HasPrefix(key, envPrefix) {
		return os.Getenv(key[len(envPrefix):]), true
	}

	switch key {
	case "system.hostname":
		// OK if there is an error; just return empty string
		name, _ := os.Hostname()
		return name, true
	case "system.slash":
		return string(filepath.Separator), true
	case "system.os":
		return runtime.GOOS, true
	case "system.wd":
		// OK if there is an error; just return empty string
		wd, _ := os.Getwd()
		return wd, true
	case "system.arch":
		return runtime.GOARCH, true
	case "time.now":
		return nowFunc(), true
	case "time.now.http":
		// According to the comment for http.TimeFormat, the timezone must be in UTC
		// to generate the correct format.
		// https://github.com/caddyserver/caddy/issues/5773
		return nowFunc().UTC().Format(http.TimeFormat), true
	case "time.now.common_log":
		return nowFunc().Format("02/Jan/2006:15:04:05 -0700"), true
	case "time.now.year":
		return strconv.Itoa(nowFunc().Year()), true
	case "time.now.unix":
		return strconv.FormatInt(nowFunc().Unix(), 10), true
	case "time.now.unix_ms":
		return strconv.FormatInt(nowFunc().UnixNano()/int64(time.Millisecond), 10), true
	}

	return nil, false
}

// readFileIntoBuffer reads the file at filePath into a size limited buffer.
func readFileIntoBuffer(filename string, size int) ([]byte, error) {
	file, err := os.Open(filename)
	if err != nil {
		return nil, err
	}
	defer file.Close()

	buffer := make([]byte, size)
	n, err := file.Read(buffer)
	if err != nil && err != io.EOF {
		return nil, err
	}

	// slice the buffer to the actual size
	return buffer[:n], nil
}

